import 'package:flutter/material.dart';

import '../design/design.dart';

/// The Agonez emblem as an in-app mark, matching the launch screen: the ink
/// drawing on light backgrounds and the gold relief on dark ones.
///
/// The images are white alpha masks generated by
/// `tool/build_brand_assets.py` and tinted here, so they follow the theme.
class AgonezEmblem extends StatelessWidget {
  const AgonezEmblem({this.size = 34, super.key});

  final double size;

  @override
  Widget build(BuildContext context) {
    final colors = context.agonezColors;
    final dark = Theme.of(context).brightness == Brightness.dark;
    return Image.asset(
      dark
          ? 'assets/brand/emblem/emblem_relief.png'
          : 'assets/brand/emblem/emblem_ink.png',
      width: size,
      height: size,
      color: dark ? colors.goldText : colors.textPrimary,
      colorBlendMode: BlendMode.srcIn,
      excludeFromSemantics: true,
    );
  }
}
